// ═══ RAW TYPE — bypasses generic safety ═══
List rawList = new ArrayList();     // raw type! No <String>!
rawList.add("Rajesh");              // OK
rawList.add(42);                    // OK! Compiler doesn't check! (unchecked warning)

// ═══ HEAP POLLUTION — wrong type sneaks in ═══
List<String> names = rawList;       // unchecked assignment! Compiler warns but allows.
String first = names.get(0);        // "Rajesh" — OK
String second = names.get(1);       // ClassCastException! 42 is Integer, not String!
// The CCE happens HERE — far from where 42 was added!

// ═══ @SafeVarargs — varargs heap pollution ═══
@SafeVarargs
static <T> List<T> toList(T... elements) {
    // T... creates Object[] at runtime (erasure!)
    // If someone stores into 'elements': elements[0] = wrongType → heap pollution
    // @SafeVarargs = "I promise I only READ from elements, never STORE into it"
    return Arrays.asList(elements);  // safe: only reads
}

// UNSAFE varargs (DO NOT use @SafeVarargs here!):
static <T> void unsafe(T... elements) {
    Object[] arr = elements;  // varargs is Object[] at runtime!
    arr[0] = 42;              // stores Integer into T[] → heap pollution!
}
