package com.bank.rawtypes;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class HeapPollutionTest {

    @SuppressWarnings({"unchecked", "rawtypes"})
    @Test
    void rawType_heapPollution_cceAtGetTime() {
        List rawList = new ArrayList();
        rawList.add("Rajesh");
        rawList.add(42);  // Integer in a "String" list

        List<String> names = rawList;  // heap pollution!
        assertThat(names.get(0)).isEqualTo("Rajesh");  // OK

        assertThatThrownBy(() -> {
            String s = names.get(1);  // CCE! Integer ≠ String!
        }).isInstanceOf(ClassCastException.class);
    }

    @SafeVarargs
    static <T> List<T> safeToList(T... elements) {
        return List.of(elements);  // only reads — safe!
    }

    @Test
    void safeVarargs_works() {
        List<String> names = safeToList("Rajesh", "Priya");
        assertThat(names).containsExactly("Rajesh", "Priya");
    }

    @Test
    void neverUseRawTypes() {
        // (Avoid) BAD: List list = new ArrayList();
        // (Recommended) GOOD: List<String> list = new ArrayList<>();
        // (Avoid) BAD: Map map = new HashMap();
        // (Recommended) GOOD: Map<String, Integer> map = new HashMap<>();
        List<String> safe = new ArrayList<>();
        safe.add("SAV2001");
        // safe.add(42);  → COMPILE ERROR! Type safety enforced!
        assertThat(safe.get(0)).isEqualTo("SAV2001");

    }
}
